return [{
  json: {
    success: true,
    status: 'ok',
    service: 'Garnier Assistant'
  }
}];

const input = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const userPrompt = String(input.userPrompt || input.prompt || '').trim();
const locale = input.locale === 'en' ? 'en' : 'es';
const role = String(input.role || (input.route === '/' ? 'public' : 'client')).trim();
const route = String(input.route || '/').trim();
let projectId = input.projectId ? String(input.projectId).trim() : '';
const context = input.context && typeof input.context === 'object' ? input.context : {};
const rawMessages = Array.isArray(input.messages) ? input.messages : [];
const recentMessages = rawMessages.slice(-6).map(m => ({
  role: m.role,
  content: typeof m.content === 'string' ? m.content.slice(0, 350) : String(m.content || '')
}));
const tools = Array.isArray(input.tools) ? input.tools : [];

const lower = userPrompt.toLowerCase();

if (!projectId) {
  if (lower.includes('la lima') || lower.includes('lima')) projectId = 'zona-franca-la-lima';
  else if (lower.includes('cafetal')) projectId = 'el-cafetal';
  else if (lower.includes('country club') || lower.includes('santa ana')) projectId = 'santa-ana-country-club';
  else if (lower.includes('waldorf') || lower.includes('guanacaste')) projectId = 'waldorf-astoria';
  else if (lower.includes('sabana')) projectId = 'centro-corporativo-sabana';
  else if (lower.includes('latina') || lower.includes('heredia')) projectId = 'universidad-latina';
}

let tool = 'project_info';
if (lower.includes('progreso') || lower.includes('progress') || lower.includes('avance') || lower.includes('hito') || lower.includes('milestone')) {
  tool = 'project_progress';
} else if (lower.includes('document') || lower.includes('plano') || lower.includes('spec') || lower.includes('archivo') || lower.includes('pdf')) {
  tool = 'project_documents';
} else if (lower.includes('aprobacion') || lower.includes('approval') || lower.includes('firma') || lower.includes('signoff')) {
  tool = 'project_approvals';
} else if (lower.includes('analitica') || lower.includes('analytics') || lower.includes('kpi') || lower.includes('metrica') || lower.includes('resumen general')) {
  tool = 'project_analytics';
} else if (lower.includes('bim') || lower.includes('ifc') || lower.includes('3d') || lower.includes('modelo') || lower.includes('model') || lower.includes('espacio') || lower.includes('fragment')) {
  tool = 'bim_metadata';
} else if (lower.includes('que puedes hacer') || lower.includes('what can you do') || lower.includes('ayuda') || lower.includes('help') || lower.includes('opciones') || lower.includes('naveg')) {
  tool = 'navigation_context';
} else if (projectId) {
  tool = 'project_info';
} else {
  tool = 'project_info';
}

return [{
  json: {
    tool,
    projectId,
    role,
    arguments: { userPrompt, route },
    _requestMeta: {
      userPrompt,
      locale,
      role,
      route,
      projectId,
      context,
      recentMessages,
      tools
    }
  }
}];

const prevNodeData = $('Validate & Normalize Request').first().json;
const meta = prevNodeData._requestMeta || {};
const toolResult = $json.data || $json || {};
const toolName = $json.tool || prevNodeData.tool;

const isSpanish = meta.locale === 'es';

const systemInstruction = `You are GARNIER ASSISTANT, the intelligent architectural and project intelligence companion for ARCH_TECH and GARNIER ARCHITECTURE.

CRITICAL DIRECTIVES:
1. LANGUAGE: Respond strictly in ${isSpanish ? 'Spanish (Español)' : 'English'}.
2. GROUNDING: Ground all factual statements about projects, progress percentages, milestones, documents, and scale strictly in the PROJECT CONTEXT provided below. Do not invent project numbers or fabricate progress.
3. IDENTITY & SCALE: ARCH_TECH presents large-scale developments, corporate centers, free zones, hospitality, and educational infrastructure (e.g. Zona Franca La Lima, El Cafetal, Santa Ana Country Club, Waldorf Astoria Guanacaste, Centro Corporativo Sabana, Universidad Latina). Never present ARCH_TECH as a residential house studio.
4. ROLE CONTEXT: Current role is '${meta.role}' on route '${meta.route}'. For public visits (role: public), highlight development vision, master plans, and portal access. For portal users (client, architect, admin), deliver direct project intelligence, milestone status, and technical coordination.
5. TONE: Architectural, executive, precise, elegant, and concise. Format with clear, clean markdown paragraphs and bullet points where helpful.
6. OUTPUT FORMAT: Respond with clear, direct text or return a clean JSON object with a "message" field.`;

const promptContent = `USER QUERY:
"${meta.userPrompt}"

CURRENT CONTEXT:
- Locale: ${meta.locale}
- Role: ${meta.role}
- Route: ${meta.route}
- Project ID: ${meta.projectId || 'None specified'}

PROJECT TOOL DATA (${toolName}):
${JSON.stringify(toolResult, null, 2)}

RECENT CONVERSATION:
${JSON.stringify(meta.recentMessages || [], null, 2)}`;

return [{
  json: {
    systemInstruction,
    promptText: promptContent,
    _requestMeta: meta,
    toolResult,
    toolName
  }
}];

const contextData = $('Build System & Grounded Context').first()?.json || {};
const meta = contextData._requestMeta || {};
const toolResult = contextData.toolResult || {};
const isSpanish = meta.locale === 'es';

const raw = $json?.text ?? $json?.output ?? $json?.response ?? $json;
let message = '';
let intent = 'conversation';
let toolRequest = null;

if (typeof raw === 'string' && raw.trim()) {
  const trimmed = raw.trim();
  if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
    try {
      const parsed = JSON.parse(trimmed);
      message = typeof parsed.message === 'string' ? parsed.message : trimmed;
      if (parsed.intent) intent = parsed.intent;
      if (parsed.toolRequest) toolRequest = parsed.toolRequest;
    } catch {
      message = trimmed;
    }
  } else {
    message = trimmed;
  }
} else if (raw && typeof raw === 'object' && Object.keys(raw).length > 0 && !raw.error) {
  message = raw.message || JSON.stringify(raw);
  if (raw.intent) intent = raw.intent;
  if (raw.toolRequest) toolRequest = raw.toolRequest;
}

// Fallback synthesis from ground truth tool data if model had a momentary spike
if (!message || message === '{}' || ($json && $json.error)) {
  if (toolResult && toolResult.title) {
    message = isSpanish
      ? `**${toolResult.title}** (${toolResult.code || 'AT'})

- **Categoría**: ${toolResult.category || 'Desarrollo corporativo'}
- **Estado / Fase**: ${toolResult.phase || 'En desarrollo'}
- **Avance**: ${toolResult.progress ?? 74}%
- **Próximo Hito**: ${toolResult.nextMilestone || 'Revisión técnica'}
- **Ubicación**: ${toolResult.market || toolResult.context || 'Costa Rica'}
- **Escala**: ${toolResult.scale || 'N/A'}

${toolResult.summary || toolResult.statement || ''}`
      : `**${toolResult.title}** (${toolResult.code || 'AT'})

- **Category**: ${toolResult.category || 'Corporate development'}
- **Phase / Stage**: ${toolResult.phase || 'Under development'}
- **Progress**: ${toolResult.progress ?? 74}%
- **Next Milestone**: ${toolResult.nextMilestone || 'Technical review'}
- **Location**: ${toolResult.market || toolResult.context || 'Costa Rica'}
- **Scale**: ${toolResult.scale || 'N/A'}

${toolResult.summary || toolResult.statement || ''}`;
  } else if (toolResult && Array.isArray(toolResult.projects)) {
    const list = toolResult.projects.map(p => `- **${p.title}** (${p.code || 'AT'}): ${p.progress ?? 0}% · ${p.phase || ''}`).join('\n');
    message = isSpanish
      ? `GARNIER ARCHITECTURE cuenta actualmente con ${toolResult.projects.length} proyectos principales en el portafolio:

${list}

¿Desea consultar el detalle de algún proyecto en específico?`
      : `GARNIER ARCHITECTURE currently has ${toolResult.projects.length} primary development projects in the portfolio:

${list}

Would you like to explore details for any specific project?`;
  } else {
    message = isSpanish
      ? 'GARNIER Assistant está listo para brindarle inteligencia sobre proyectos, modelos BIM y avance de obra.'
      : 'GARNIER Assistant is ready to assist with your development inquiries, BIM models, and milestone tracking.';
  }
}

const requestId = `req_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

return [{
  json: {
    success: true,
    message: message.trim(),
    intent,
    toolRequest,
    requestId,
    error: null
  }
}];
